import { useStyleRegister } from '@ant-design/cssinjs';
import { TinyColor } from '@ctrl/tinycolor';
import { ConfigProvider as AntdConfigProvider, theme as antdTheme } from 'antd';
import { useContext, useMemo, useRef } from 'react';
import { ProProvider } from "../index";
/**
 * 把一个颜色设置一下透明度
 * @example (#fff, 0.5) => rgba(255, 255, 255, 0.5)
 * @param baseColor {string}
 * @param alpha {0-1}
 * @returns rgba {string}
 */
export const setAlpha = (baseColor, alpha) => new TinyColor(baseColor).setAlpha(alpha).toRgbString();

/**
 * 把一个颜色修改一些明度
 * @example (#000, 50) => #808080
 * @param baseColor {string}
 * @param brightness {0-100}
 * @returns hexColor {string}
 */
export const lighten = (baseColor, brightness) => {
  const instance = new TinyColor(baseColor);
  return instance.lighten(brightness).toHexString();
};
// 为了兼容 antd 类型，这里使用 any
export const proTheme = antdTheme;
export const resetComponent = token => ({
  boxSizing: 'border-box',
  margin: 0,
  padding: 0,
  color: token.colorText,
  fontSize: token.fontSize,
  lineHeight: token.lineHeight,
  listStyle: 'none',
  '*, *::before, *::after': {
    boxSizing: 'border-box'
  }
});
export const operationUnit = token => ({
  // FIXME: This use link but is a operation unit. Seems should be a colorPrimary.
  // And Typography use this to generate link style which should not do this.
  color: token.colorLink,
  outline: 'none',
  cursor: 'pointer',
  transition: `color ${token.motionDurationSlow}`,
  '&:focus, &:hover': {
    color: token.colorLinkHover
  },
  '&:active': {
    color: token.colorLinkActive
  }
});
const hashString = input => {
  let hash = 5381;
  for (let i = 0; i < input.length; i += 1) {
    hash = hash * 33 ^ input.charCodeAt(i);
  }
  return (hash >>> 0).toString(36);
};
const getProTokenKey = token => {
  try {
    // ProProvider exposes finalToken instead of useCacheToken token,
    // so build a stable key from Pro token payload directly.
    return hashString(JSON.stringify(token));
  } catch {
    return '';
  }
};

/**
 * 封装了一下 antd 的 useStyle
 * @param componentName {string} 组件的名字
 * @param styleFn {GenerateStyle} 生成样式的函数
 * @returns UseStyleResult
 */
export function useStyle(componentName, styleFn) {
  let {
    token = {},
    hashed
  } = useContext(ProProvider);
  const {
    token: antdToken,
    hashId,
    theme
  } = antdTheme.useToken();
  const {
    getPrefixCls,
    csp
  } = useContext(AntdConfigProvider.ConfigContext);

  // 如果不在 ProProvider 里面，就用 antd 的
  if (!token.layout) {
    token = {
      ...antdToken
    };
  }
  token.proComponentsCls = token.proComponentsCls ?? `.${getPrefixCls('pro')}`;
  token.antCls = `.${getPrefixCls()}`;

  // Register styles (side effect only in v2)
  // Keep path sensitive to both antd theme and Pro token updates.
  const proTokenKey = useMemo(() => {
    return getProTokenKey(token);
  }, [token]);

  // Keep path monotonic across toggles to avoid style order issues
  // when switching dark -> light (back to an old key).
  const styleKey = [hashId, theme.id, token.themeId, proTokenKey].filter(Boolean).join('-');
  const lastStyleKeyRef = useRef('');
  const styleVersionRef = useRef(0);
  if (lastStyleKeyRef.current !== styleKey) {
    styleVersionRef.current += 1;
    lastStyleKeyRef.current = styleKey;
  }
  const stylePath = [componentName, styleKey, styleVersionRef.current].filter(Boolean);
  useStyleRegister({
    theme: theme,
    token,
    path: stylePath,
    nonce: csp?.nonce,
    layer: {
      name: 'antd-pro'
    }
  }, () => styleFn(token));
  return {
    wrapSSR: node => node,
    hashId: hashed ? hashId : ''
  };
}